task.vi:
Tìm lỗi trong mỗi đoạn mã sau và sửa lại cho đúng:
a) #include <iostream>;
b) arraySize = 10; // với arraySize đã khai báo là const
c) Giả sử có: array< int, 10 > b = {};
   for ( size_t i = 0; i <= b.size(); ++i )
       b[ i ] = 1;
d) Giả sử a là mảng hai chiều kiểu int có 2 hàng và 2 cột:
   a[ 1, 1 ] = 5;

task.en:
Find the error in each of the following program segments and correct the error:
a) #include <iostream>;
b) arraySize = 10; // arraySize was declared const
c) Assume that array< int, 10 > b = {};
   for ( size_t i = 0; i <= b.size(); ++i )
       b[ i ] = 1;
d) Assume that a is a two-dimensional array of int values with two rows and two columns:
   a[ 1, 1 ] = 5;

example.code:
#include <iostream>
#include <array>
#include <algorithm>

class GradeBook {
public:
    static constexpr size_t students = 5;
};

int main() {
    std::array<int, GradeBook::students> scores{88, 55, 92, 70, 60};

    std::sort(scores.begin(), scores.end());

    std::cout << "Sorted: ";
    for (auto score : scores) {
        std::cout << score << " ";
    }
    std::cout << "\n";

    int searchKey = 70;
    bool found = std::binary_search(scores.begin(), scores.end(), searchKey);
    std::cout << "Key " << searchKey << (found ? " found" : " not found") << "\n";

    return 0;
}

#include <iostream>
#include <array>
#include <iomanip>

int main() {
    constexpr size_t rows = 3;
    constexpr size_t cols = 3;
    std::array<std::array<int, cols>, rows> table{};

    int counter = 1;
    for (size_t r = 0; r < table.size(); ++r) {
        for (size_t c = 0; c < table[r].size(); ++c) {
            table[r][c] = counter++;
        }
    }

    std::cout << "     [0]  [1]  [2]\n";
    for (size_t r = 0; r < rows; ++r) {
        std::cout << '[' << r << "] ";
        for (size_t c = 0; c < cols; ++c) {
            std::cout << std::setw(3) << table[r][c] << "  ";
        }
        std::cout << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v1(3); // initialized to 0
    v1[0] = 10; // modifiable lvalue
    v1[1] = 20;
    v1[2] = 30;

    std::vector<int> v2 = v1; // copy assignment / initialization

    std::cout << "v1 size: " << v1.size() << "\n";
    std::cout << "v1 == v2: " << std::boolalpha << (v1 == v2) << "\n";

    v2[1] = 99;
    std::cout << "v1 != v2: " << (v1 != v2) << "\n";

    const std::vector<int> constV = {1, 2, 3};
    int val = constV[0]; // read access is allowed
    std::cout << "constV[0]: " << val << "\n";
    // constV[0] = 5; // Error: constV[0] is a nonmodifiable lvalue

    return 0;
}

#include <iostream>
#include <vector>
#include <stdexcept>

void checkAndPrint(const std::vector<int>& v, size_t index) {
    if (index >= v.size()) {
        throw std::out_of_range("Index out of range");
    }
    std::cout << "Element at " << index << ": " << v[index] << "\n";
}

int main() {
    std::vector<int> values{10, 20, 30};

    try {
        checkAndPrint(values, 1);
        checkAndPrint(values, 5);
    }
    catch (const std::out_of_range& ex) {
        std::cout << "Exception caught: " << ex.what() << "\n";
    }

    std::cout << "Program continues normally after recovery.\n";
    return 0;
}
